USE xlx;

INSERT IGNORE INTO site_config (config_key, config_value, description) VALUES
('faq_page_groups', '[{"title":"产品相关","items":[{"q":"你们主要生产哪些产品？","a":"我们主要生产两大类产品：金属丝类（镀锌铁丝、不锈钢丝、退火丝、PVC涂塑丝等）和丝网类（电焊网片、荷兰网、护栏网、窗纱、钢板网、钢格板等）。"},{"q":"产品可以定制吗？","a":"可以。我们支持来图来样定制加工，可以根据您的需求定制不同材质、规格、尺寸的产品。定制产品一般15-30个工作日交货。"},{"q":"产品的质量标准是什么？","a":"所有产品均按照国家标准生产，部分产品可按国际标准（ISO、EN等）生产。每批产品均附带质检报告和材质证书。"},{"q":"可以提供样品吗？","a":"可以提供免费样品，运费到付。样品一般3-5个工作日准备好并寄出。"}]},{"title":"订单与付款","items":[{"q":"最小起订量是多少？","a":"不同产品起订量不同。常规产品一般100公斤起订，定制产品视具体情况而定。具体请联系我们获取详细信息。"},{"q":"支持哪些付款方式？","a":"我们支持T/T（电汇）、L/C（信用证）、Western Union等多种国际付款方式。具体付款方式可根据订单金额和双方协商确定。"},{"q":"交货周期多长？","a":"常规产品7-15个工作日，定制产品15-30个工作日。具体交期视产品类型、订单数量和当时产能而定，下单时会与您确认具体交期。"},{"q":"可以接受FOB/CIF等贸易方式吗？","a":"可以。我们支持FOB、CIF、CFR等多种国际贸易条款，可以根据您的需求灵活安排。"}]},{"title":"物流与售后","items":[{"q":"如何安排物流运输？","a":"国内订单可走物流或快递；出口订单可安排海运、空运或铁路运输。我们与多家货代公司有长期合作，可以为您提供优惠的运输方案。"},{"q":"包装方式是怎样的？","a":"常规产品采用编织袋或纸箱包装，出口产品可按客户要求进行中性包装或定制包装。所有包装均经过防潮、防锈处理。"},{"q":"如果收到的产品有质量问题怎么办？","a":"如有质量问题，请在收到货物后7天内联系我们并提供照片或视频证据。经确认后，我们将免费补发或退款。"},{"q":"是否提供售后服务？","a":"是的。我们提供完善的售后服务，包括产品使用指导、质量问题处理、返单优惠等。每位客户都有专属业务经理对接。"}]}]', 'FAQ页面分组内容（JSON格式，含title和items）');
